export const title = "How to Place a Headset Hanger Without Blocking Your Chair";
export const metaTitle = "Where to Place a Headset Hanger on a Desk";
export const metaDescription = "Check a headset hanger’s mounting surface, full headset envelope, chair movement, cable route, and one-hand retrieval. A research-based guide from DeskFinds.";
